        drop = set(columns)
        self._require_all(drop)
        remaining = [c for c in self._columns if c not in drop]
        if not remaining:
            raise ValueError("cannot drop every column")
        return self._clone(columns=remaining, rows=self._rows)

    def rename_columns(self, mapping):
        renamed = [mapping.get(c, c) for c in self._columns]
        if len(set(renamed)) != len(renamed):
            raise ValueError("rename would create duplicate column names")
        rows = [{mapping.get(c, c): row[c] for c in self._columns} for row in self._rows]
        return self._clone(columns=renamed, rows=rows)

    def strip_whitespace(self, columns=None):
        target = self._resolve_columns(columns)
        rows = []
        for row in self._rows:
            new = dict(row)
            for c in target:
                v = new[c]
                if isinstance(v, str):
                    new[c] = v.strip()
            rows.append(new)
        return self._clone(rows=rows)

    def drop_duplicates(self, subset=None):
        target = self._resolve_columns(subset)
        seen = set()
        rows = []
        for row in self._rows:
