def load_csv(source, delimiter=",", encoding="utf-8", has_header=True, skip_blank_lines=True):
    """Load a CSV file into a DataTable. source may be a path or file-like."""
    try:
        if hasattr(source, "read"):
            return _read(source, delimiter, has_header, skip_blank_lines)
        with open(os.fspath(source), "r", encoding=encoding, newline="") as handle:
            return _read(handle, delimiter, has_header, skip_blank_lines)
    except CSVLoadError:
        raise
    except OSError as exc:
        raise CSVLoadError(f"could not read {source!r}: {exc}") from exc


def load_csv_string(text, delimiter=",", has_header=True, skip_blank_lines=True):
    return _read(io.StringIO(text), delimiter, has_header, skip_blank_lines)


def _read(handle, delimiter, has_header, skip_blank_lines):
    reader = csv.reader(handle, delimiter=delimiter)
    try:
        parsed = list(reader)
    except csv.Error as exc:
        raise CSVLoadError(f"invalid CSV: {exc}") from exc
    if skip_blank_lines:
        parsed = [row for row in parsed if any(cell.strip() for cell in row)]
    if not parsed:
        raise CSVLoadError("CSV source contains no data")
    if has_header:
        header = _sanitize_header(parsed[0])
        data = parsed[1:]
    else:
        width = len(parsed[0])
        header = _sanitize_header(["" for _ in range(width)])
        data = parsed
    rows = [_fit(row, len(header)) for row in data]
    return DataTable(header, rows)
