"""Internal helpers shared across the tabular package."""

from __future__ import annotations

from typing import Any, Optional


def is_missing(value: Any) -> bool:
    """Return True for values treated as missing (``None`` or blank strings)."""
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip() == ""
    return False


def to_number(value: Any) -> Optional[float]:
    """Coerce ``value`` to a float, or return ``None`` if it is not numeric."""
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str) and value.strip():
        try:
            return float(value.strip())
        except ValueError:
            return None
    return None

"""Exception hierarchy for the tabular package."""

from __future__ import annotations

from typing import Any


class TabularError(Exception):
    """Base class for every error raised by :mod:`tabular`."""


class CSVLoadError(TabularError):
    """Raised when a CSV source cannot be read or parsed."""


class ColumnNotFoundError(TabularError, KeyError):
    """Raised when a requested column is not present in a table."""

    def __init__(self, column: Any) -> None:
        super().__init__(column)
        self.column = column

    def __str__(self) -> str:
        return f"unknown column: {self.column!r}"

"""Cleaning operations for :class:`tabular.DataTable`.

Every method returns a new :class:`~tabular.table.DataTable`; the receiver is
never modified.
"""

from __future__ import annotations

from typing import Any, Iterable, Mapping, Optional, Sequence

from ._util import is_missing


def _coerce_value(value: Any) -> Any:
    """Convert a string to ``int`` or ``float`` when it represents a number."""
    if not isinstance(value, str):
        return value
    text = value.strip()
    if not text:
        return value
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return value


class CleaningMixin:
    """Mixin providing cleaning methods to :class:`tabular.DataTable`."""

    def _resolve_columns(self, columns: Optional[Iterable[str]]) -> list:
        if columns is None:
            return list(self._columns)
        resolved = list(columns)
        self._require_all(resolved)
        return resolved

    def select_columns(self, columns: Sequence[str]):
        """Return a table containing only ``columns``, in the given order."""
        selected = list(columns)
        self._require_all(selected)
        return self._clone(columns=selected, rows=self._rows)

    def drop_columns(self, columns: Sequence[str]):
        """Return a table with ``columns`` removed."""
        dropped = set(columns)
        self._require_all(dropped)
        remaining = [column for column in self._columns if column not in dropped]
        if not remaining:
            raise ValueError("cannot drop every column")
        return self._clone(columns=remaining, rows=self._rows)

    def rename_columns(self, mapping: Mapping[str, str]):
        """Return a table with columns renamed according to ``mapping``."""
        renamed = [mapping.get(column, column) for column in self._columns]
        if len(set(renamed)) != len(renamed):
            raise ValueError("rename would create duplicate column names")
        rows = [
            {mapping.get(column, column): row[column] for column in self._columns}
            for row in self._rows
        ]
        return self._clone(columns=renamed, rows=rows)

    def strip_whitespace(self, columns: Optional[Sequence[str]] = None):
        """Strip leading/trailing whitespace from string cells."""
        target = self._resolve_columns(columns)
        rows = []
        for row in self._rows:
            updated = dict(row)
            for column in target:
                value = updated[column]
                if isinstance(value, str):
                    updated[column] = value.strip()
            rows.append(updated)
        return self._clone(rows=rows)

    def drop_duplicates(self, subset: Optional[Sequence[str]] = None):
        """Return a table with duplicate rows removed (first occurrence kept)."""
        target = self._resolve_columns(subset)
        seen = set()
        rows = []
        for row in self._rows:
            key = tuple(row[column] for column in target)
            if key in seen:
                continue
            seen.add(key)
            rows.append(dict(row))
        return self._clone(rows=rows)

    def drop_missing(self, subset: Optional[Sequence[str]] = None, how: str = "any"):
        """Drop rows with missing values.

        ``how="any"`` removes a row when any selected cell is missing;
        ``how="all"`` removes it only when every selected cell is missing.
        """
        if how not in ("any", "all"):
            raise ValueError("how must be 'any' or 'all'")
        target = self._resolve_columns(subset)
        rows = []
        for row in self._rows:
            missing = sum(1 for column in target if is_missing(row[column]))
            if how == "any" and missing:
                continue
            if how == "all" and missing == len(target):
                continue
            rows.append(dict(row))
        return self._clone(rows=rows)

    def fill_missing(self, value: Any, subset: Optional[Sequence[str]] = None):
        """Replace missing cells with ``value``.

        ``value`` may be a scalar applied to every column or a mapping of
        column name to replacement.
        """
        target = self._resolve_columns(subset)
        rows = []
        for row in self._rows:
            updated = dict(row)
            for column in target:
                if not is_missing(updated[column]):
                    continue
                if isinstance(value, Mapping):
                    replacement = value.get(column)
                    if replacement is not None:
                        updated[column] = replacement
                else:
                    updated[column] = value
            rows.append(updated)
        return self._clone(rows=rows)

    def convert_types(self, columns: Optional[Sequence[str]] = None):
        """Convert numeric-looking string columns to ``int`` or ``float``.

        A column is converted only when every non-missing value parses as a
        number; otherwise it is left untouched.
        """
        target = self._resolve_columns(columns)
        convertible = set()
        for column in target:
            values = [row[column] for row in self._rows if not is_missing(row[column])]
            if values and all(
                isinstance(_coerce_value(value), (int, float))
                and not isinstance(value, bool)
                for value in values
            ):
                convertible.add(column)

        rows = []
        for row in self._rows:
            updated = dict(row)
            for column in convertible:
                if not is_missing(updated[column]):
                    updated[column] = _coerce_value(updated[column])
            rows.append(updated)
        return self._clone(rows=rows)

"""Analysis operations for :class:`tabular.DataTable`."""

from __future__ import annotations

import math
from statistics import mean as _mean
from statistics import median as _median
from statistics import stdev as _stdev
from statistics import variance as _variance
from typing import Iterable, Optional

from ._util import is_missing, to_number
from .errors import TabularError


class AnalysisMixin:
    """Mixin providing descriptive-statistics methods to DataTable."""

    def _numbers_optional(self, column: str) -> list:
        """Return numeric values from ``column`` as floats (missing/non-numeric skipped)."""
        numbers = []
        for value in self.column(column):
            number = to_number(value)
            if number is not None:
                numbers.append(number)
        return numbers

    def _numbers(self, column: str) -> list:
        numbers = self._numbers_optional(column)
        if not numbers:
            raise TabularError(f"column {column!r} contains no numeric values")
        return numbers

    def count(self, column: Optional[str] = None) -> int:
        """Number of rows, or number of non-missing values in ``column``."""
        if column is None:
            return len(self)
        self._require(column)
        return sum(1 for value in self.column(column) if not is_missing(value))

    def sum(self, column: str) -> float:
        """Sum of the numeric values in ``column``."""
        return sum(self._numbers(column))

    def mean(self, column: str) -> float:
        """Arithmetic mean of the numeric values in ``column``."""
        return _mean(self._numbers(column))

    def median(self, column: str) -> float:
        """Median of the numeric values in ``column``."""
        return _median(self._numbers(column))

    def min(self, column: str) -> float:
        """Smallest numeric value in ``column``."""
        return min(self._numbers(column))

    def max(self, column: str) -> float:
        """Largest numeric value in ``column``."""
        return max(self._numbers(column))

    def variance(self, column: str) -> float:
        """Sample variance of the numeric values in ``column``."""
        numbers = self._numbers(column)
        if len(numbers) < 2:
            raise TabularError(f"column {column!r} needs at least two values")
        return _variance(numbers)

    def stdev(self, column: str) -> float:
        """Sample standard deviation of the numeric values in ``column``."""
        numbers = self._numbers(column)
        if len(numbers) < 2:
            raise TabularError(f"column {column!r} needs at least two values")
        return _stdev(numbers)

    def value_counts(self, column: str, dropna: bool = True) -> dict:
        """Count occurrences of each value in ``column``, most frequent first."""
        self._require(column)
        counts = {}
        for value in self.column(column):
            if is_missing(value):
                if dropna:
                    continue
                key = value
            else:
                key = value
            try:
                counts[key] = counts.get(key, 0) + 1
            except TypeError:
                text = str(key)
                counts[text] = counts.get(text, 0) + 1
        return dict(sorted(counts.items(), key=lambda item: item[1], reverse=True))

    def describe(self, columns: Optional[Iterable[str]] = None) -> dict:
        """Return summary statistics for each column.

        Numeric columns report count/mean/min/max/median (plus stdev when at
        least two values exist); other columns report count/unique/top/freq.
        """
        target = self._resolve_columns(columns)
        summary = {}
        for column in target:
            values = self.column(column)
            present = sum(1 for value in values if not is_missing(value))
            numbers = self._numbers_optional(column)
            if numbers:
                stats = {
                    "count": present,
                    "numeric_count": len(numbers),
                    "mean": _mean(numbers),
                    "min": min(numbers),
                    "max": max(numbers),
                    "median": _median(numbers),
                }
                if len(numbers) >= 2:
                    stats["stdev"] = _stdev(numbers)
                summary[column] = stats
            else:
                counts = self.value_counts(column)
                top, freq = next(iter(counts.items()), (None, 0))
                summary[column] = {
                    "count": present,
                    "unique": len(counts),
                    "top": top,
                    "freq": freq,
                }
        return summary

    def correlation(self, x: str, y: str) -> float:
        """Pearson correlation between numeric columns ``x`` and ``y``."""
        self._require(x)
        self._require(y)
        xs, ys = [], []
        for row in self._rows:
            first = to_number(row[x])
            second = to_number(row[y])
            if first is None or second is None:
                continue
            xs.append(first)
            ys.append(second)
        if len(xs) < 2:
            raise TabularError("correlation needs at least two paired numeric values")
        mean_x = _mean(xs)
        mean_y = _mean(ys)
        covariance = sum((a - mean_x) * (b - mean_y) for a, b in zip(xs, ys))
        spread_x = math.sqrt(sum((a - mean_x) ** 2 for a in xs))
        spread_y = math.sqrt(sum((b - mean_y) ** 2 for b in ys))
        if spread_x == 0 or spread_y == 0:
            raise TabularError("correlation is undefined for constant data")
        return covariance / (spread_x * spread_y)

"""Core table type for the tabular package."""

from __future__ import annotations

import csv
import io
import os
from typing import Any, Iterable, Iterator, Mapping, Optional

from .analysis import AnalysisMixin
from .cleaning import CleaningMixin
from .errors import ColumnNotFoundError


class DataTable(CleaningMixin, AnalysisMixin):
    """A lightweight, dependency-free table of values.

    Rows are stored as mappings keyed by column name. Loading, cleaning and
    analysis are exposed as methods; cleaning methods return new tables and
    never mutate the receiver.
    """

    __slots__ = ("_columns", "_rows")

    def __init__(self, columns: Iterable[str], rows: Iterable[Any]) -> None:
        columns = list(columns)
        if not columns:
            raise ValueError("a table needs at least one column")
        if len(set(columns)) != len(columns):
            raise ValueError("column names must be unique")

        known = set(columns)
        normalized = []
        for index, row in enumerate(rows):
            if isinstance(row, Mapping):
                unknown = set(row) - known
                if unknown:
                    raise ValueError(f"row {index} has unknown columns: {sorted(unknown)}")
                normalized.append({column: row.get(column) for column in columns})
            else:
                values = list(row)
                if len(values) != len(columns):
                    raise ValueError(
                        f"row {index} has {len(values)} values, expected {len(columns)}"
                    )
                normalized.append(dict(zip(columns, values)))

        self._columns = tuple(columns)
        self._rows = normalized

    @classmethod
    def from_rows(cls, header: Iterable[str], rows: Iterable[Any]) -> "DataTable":
        """Build a table from a header and an iterable of row sequences."""
        return cls(list(header), [list(row) for row in rows])

    # ------------------------------------------------------------------
    # Introspection / access
    # ------------------------------------------------------------------
    @property
    def columns(self) -> tuple:
        """Column names, in order."""
        return self._columns

    @property
    def rows(self) -> list:
        """A copy of the table's rows as dictionaries."""
        return [dict(row) for row in self._rows]

    def column(self, name: str) -> list:
        """Return the values of a single column as a list."""
        self._require(name)
        return [row[name] for row in self._rows]

    def to_dicts(self) -> list:
        """Return the rows as a list of dictionaries."""
        return [dict(row) for row in self._rows]

    def to_columns(self) -> dict:
        """Return a mapping of column name to list of values."""
        return {column: self.column(column) for column in self._columns}

    def __len__(self) -> int:
        return len(self._rows)

    def __iter__(self) -> Iterator[dict]:
        for row in self._rows:
            yield dict(row)

    def __getitem__(self, column: str) -> list:
        return self.column(column)

    def __contains__(self, column: object) -> bool:
        return column in self._columns

    def __repr__(self) -> str:
        return f"DataTable(rows={len(self._rows)}, columns={list(self._columns)})"

    # ------------------------------------------------------------------
    # CSV output
    # ------------------------------------------------------------------
    def to_csv(self, path: Any, delimiter: str = ",", encoding: str = "utf-8") -> None:
        """Write the table to ``path`` as CSV."""
        with open(os.fspath(path), "w", encoding=encoding, newline="") as handle:
            self._write(handle, delimiter)

    def to_csv_string(self, delimiter: str = ",") -> str:
        """Render the table as a CSV string."""
        buffer = io.StringIO()
        self._write(buffer, delimiter)
        return buffer.getvalue()

    def _write(self, handle: Any, delimiter: str) -> None:
        writer = csv.writer(handle, delimiter=delimiter)
        writer.writerow(self._columns)
        for row in self._rows:
            writer.writerow(
                ["" if row[column] is None else row[column] for column in self._columns]
            )

    # ------------------------------------------------------------------
    # Internal helpers used by the mixins
    # ------------------------------------------------------------------
    def _require(self, column: str) -> str:
        if column not in self._columns:
            raise ColumnNotFoundError(column)
        return column

    def _require_all(self, columns: Iterable[str]) -> None:
        for column in columns:
            self._require(column)

    def _clone(
        self,
        columns: Optional[Iterable[str]] = None,
        rows: Optional[Iterable[Any]] = None,
    ) -> "DataTable":
        columns = tuple(self._columns if columns is None else columns)
        rows = self._rows if rows is None else list(rows)
        if columns != self._columns:
            rows = [{column: row.get(column) for column in columns} for row in rows]
        return DataTable(columns, rows)

